import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel source (CUDA)
matmul_kernel_source = """
__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int i = idx / N; // row index in output
        int j = idx % N; // column index in output
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[i * K + k] * B[k * N + j];
        }
        C[idx] = sum;
    }
}
"""

# Function signature source (C++)
matmul_function_source = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

# Full CUDA function that allocates output and launches kernel
matmul_cuda_full_source = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    float* out_ptr;
    C_tensor = torch::empty({M, N}, A.dtype()); // allocate output tensor

    const int block_size = 256;
    const int num_blocks = (M * N + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float()>, B.data_ptr<float()>, out_ptr, M, K, N);

    return C_tensor;
}
"""

# Combine kernel and full function into a single cuda source string
matmul_cuda_source = matmul_kernel_source + "\n" + matmul_cuda_full_source

elementmatmul = load_inline(
    name="matmul_cuda",
    cpp_sources=matmul_function_source,
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul = elementmatmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul(A, B)
